import matplotlib.pyplot as plt
import networkx as nx

# Generated by Claude Code Sonnet 5.5

def make_visualizer(pages, pause=0.8):
    G = nx.DiGraph()
    for p in pages:
        G.add_node(p.name)
    for p in pages:
        for link in p.links:
            G.add_edge(p.name, link.target.name, weight=link.weight)

    pos = nx.circular_layout(G)               # evenly spaced, computed once
    plt.ion()
    fig, ax = plt.subplots(figsize=(9, 7))

    def draw(iteration, diff):
        ax.clear()
        ranks = [p.rank for p in pages]
        sizes = [r * 6000 for r in ranks]

        nx.draw_networkx_nodes(
            G, pos, ax=ax,
            node_size=sizes,
            node_color=ranks, cmap=plt.cm.Blues,
            vmin=0, vmax=max(ranks) * 1.2,
            edgecolors="black", linewidths=0.8)
        nx.draw_networkx_edges(
            G, pos, ax=ax, arrows=True, arrowsize=15,
            node_size=sizes,                   # arrowheads stop at the node edge
            width=[G[u][v]["weight"] * 4 for u, v in G.edges()],
            edge_color="gray", alpha=0.7,
            connectionstyle="arc3,rad=0.15")
        nx.draw_networkx_labels(
            G, pos, ax=ax,
            labels={p.name: f"{p.name}\n{p.rank:.3f}" for p in pages},
            font_size=8)
        change = "start" if diff is None else f"change = {diff:.6f}"
        ax.set_title(f"Iteration {iteration}  ({change})")
        ax.margins(0.15)                       # keeps large nodes from clipping
        ax.axis("off")
        plt.pause(pause)

    return draw